// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.trace.BrainTraceimport timber.log.Timberimport java.time.Instantimport java.util.concurrent.ConcurrentLinkedQueueimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain Trace Policy (retention + cleanup). * * Manages the lifecycle of [BrainTrace] audit logs: *   - In-memory cache for recent traces (fast UI access) *   - Auto-expire after configurable retention period *   - Auto-archive old traces to ZIP (for export) *   - User-configurable retention (default 90 days) * * ## Why a Policy? * * BrainTraces are detailed — each one can be 1-10 KB (with all layer decisions). * At 100 requests/day, that's 100KB-1MB/day, 3-30MB/month. Without cleanup: *   - Storage fills up *   - UI slows down (loading thousands of traces) *   - Privacy concern (years of history) * * ## Privacy * *   - Traces never leave the device (unless user explicitly exports) *   - User can view + delete in Settings → Privacy → Audit Log *   - Auto-expire protects privacy (old data forgotten) *   - Export creates encrypted ZIP (user holds the key) * * @see <a href="docs/spec/module2-spec-review.pdf">§10.6 Trace Policy</a> */@Singletonclass BrainTracePolicy @Inject constructor(    private val maxCachedTraces: Int,    private val retentionDays: Long,) {    private val cachedTraces = ConcurrentLinkedQueue<DatedTrace>()    /**     * Add a trace to the cache.     *     * Called by [BrainOrchestrator] after every request.     */    @Synchronized    fun addTrace(trace: BrainTrace, timestamp: Instant = Instant.now()) {        cachedTraces.add(DatedTrace(trace = trace, timestamp = timestamp))        // Trim if over capacity (remove oldest)        while (cachedTraces.size > maxCachedTraces) {            cachedTraces.poll()        }        Timber.tag("NOUS.Trace").v("Trace cached: %s (total=%d)", trace.correlationId.value.take(8), cachedTraces.size)    }    /**     * Get all cached traces (for Settings → Privacy → Audit Log).     */    fun getAll(): List<BrainTrace> = cachedTraces.map { it.trace }.toList()    /**     * Get recent traces (last N).     */    fun getRecent(limit: Int = 50): List<BrainTrace> =        cachedTraces.toList().takeLast(limit).map { it.trace }    /**     * Get a specific trace by correlation ID.     */    fun getById(correlationId: com.roshan.persona.common.CorrelationId): BrainTrace? =        cachedTraces.find { it.trace.correlationId == correlationId }?.trace    /**     * Delete a specific trace (user-initiated).     */    @Synchronized    fun deleteById(correlationId: com.roshan.persona.common.CorrelationId): Boolean {        val removed = cachedTraces.removeIf { it.trace.correlationId == correlationId }        if (removed) {            Timber.tag("NOUS.Trace").i("Trace deleted: %s", correlationId.value.take(8))        }        return removed    }    /**     * Delete all traces (Settings → Privacy → Clear All).     */    @Synchronized    fun clearAll() {        val count = cachedTraces.size        cachedTraces.clear()        Timber.tag("NOUS.Trace").i("Cleared all traces: %d", count)    }    /**     * Clean up traces older than [retentionDays].     *     * Called periodically by WorkManager (daily).     *     * @return number of traces removed     */    @Synchronized    fun cleanupExpired(now: Instant = Instant.now()): Int {        val cutoff = now.minusSeconds(retentionDays * 24 * 60 * 60)        val before = cachedTraces.size        cachedTraces.removeIf { it.timestamp.isBefore(cutoff) }        val removed = before - cachedTraces.size        if (removed > 0) {            Timber.tag("NOUS.Trace").i("Cleaned up %d expired traces (older than %d days)", removed, retentionDays)        }        return removed    }    /**     * Export traces to an encrypted ZIP (for user backup).     *     * Real impl in Module 3 (uses EncryptedFile + ZIP streaming).     * For Module 2, returns the traces as a list (caller handles serialization).     */    fun exportForBackup(): List<BrainTrace> = getAll()    /**     * Get stats (for Settings → Privacy → Audit Log → Stats).     */    fun getStats(): TracePolicyStats {        return TracePolicyStats(            cachedCount = cachedTraces.size,            retentionDays = retentionDays,            oldestTimestamp = cachedTraces.minByOrNull { it.timestamp }?.timestamp,            newestTimestamp = cachedTraces.maxByOrNull { it.timestamp }?.timestamp,        )    }    /**     * Internal wrapper — pairs a trace with its cache timestamp.     */    private data class DatedTrace(        val trace: BrainTrace,        val timestamp: Instant,    )    companion object {        /** Default retention: 90 days. */        const val DEFAULT_RETENTION_DAYS = 90L        /** Short retention: 7 days (for privacy-conscious users). */        const val SHORT_RETENTION_DAYS = 7L        /** Long retention: 1 year (for power users / debugging). */        const val LONG_RETENTION_DAYS = 365L    }}/** * Stats about the trace cache. */data class TracePolicyStats(    val cachedCount: Int,    val retentionDays: Long,    val oldestTimestamp: Instant?,    val newestTimestamp: Instant?,)